package vn.rtr.aeris.control01;
import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import vn.rtr.aeris.betaintegrated01.RunLifecycle;
import vn.rtr.aeris.beta01runtime.*;

/** UI release and local dispatch-entry CAS. Neither is a remote/kernel execution attestation. */
public final class ReleaseControl {
    public interface Recorder {void persist(Cancel cancellation)throws Exception;}
    public static final class Notice {
        public final long oldFence,newFence,touchRevision;private final Map<String,Object>rawMotion,template;private final RunLifecycle.Clock clock;
        private static final class Materialized {final Map<String,Object>row;final byte[]bytes;final String sha;final long observedAtNs;Materialized(Map<String,Object>r,long at){row=freeze(r);bytes=Values.bytes(row);sha=Values.hash(bytes);observedAtNs=at;}}
        private final AtomicReference<Materialized>value=new AtomicReference<>();
        private Notice(Map<String,Object>r,Map<String,Object>raw,long a,long b,long revision,RunLifecycle.Clock clock){template=freeze(r);rawMotion=freeze(raw);oldFence=a;newFence=b;touchRevision=revision;this.clock=clock;}
        /** Called only after handle is reachable through the successful release CAS. Upper bound, not an exact publication instant. */
        private Materialized materialize()throws IOException {Materialized current=value.get();if(current!=null)return current;long at=clock.monotonicNs(),receipt=integer(((Map<?,?>)template.get("motionContext")).get("receiptElapsedNs"));if(at<receipt||at-receipt>ControlAuthority.TTL_NS)throw new IOException("RELEASE_POST_CAS_OBSERVATION_STALE");Map<String,Object>r=new LinkedHashMap<>(template);r.put("observedAtNs",at);Materialized candidate=new Materialized(r,at);value.compareAndSet(null,candidate);return value.get();}
        public Map<String,Object>row()throws IOException{return materialize().row;}public byte[]bytes()throws IOException{return materialize().bytes.clone();}public String sha()throws IOException{return materialize().sha;}public long observedAtNs()throws IOException{return materialize().observedAtNs;}public Map<String,Object>rawMotion(){return rawMotion;}
    }
    public static final class Permit {public final long serial,fence,claimObservedNs;Permit(long s,long f,long n){serial=s;fence=f;claimObservedNs=n;}public Map<String,Object>row(){return Values.map("serial",serial,"releaseFence",fence,"claimObservedNs",claimObservedNs,"meaning","LOCAL_DISPATCH_ENTRY_PERMIT_NOT_KERNEL_OR_REMOTE_ATTESTATION");}}
    private static final class State {final long fence,permit;final List<Notice>history;State(long f,long p,List<Notice>h){fence=f;permit=p;history=h;}}
    public static final class Cancel extends NativeSegments.ExpectedCancellation {
        public final ControlAuthority.Input input;public final String phase;public final long oldFence,newFence,decisionNs;public final List<Notice>notices;private final ReleaseControl owner;
        private Map<String,Object>detail;private Cancel(ReleaseControl o,ControlAuthority.Input i,String p,long a,long b,long decision,List<Notice>n){super("EXPECTED_RELEASE_CANCELLATION");owner=o;input=i;phase=p;oldFence=a;newFence=b;decisionNs=decision;notices=Collections.unmodifiableList(new ArrayList<>(n));}
        public void persistWitness()throws Exception {if(owner.recorder==null)throw new IOException("RELEASE_RECORDER_REQUIRED");owner.recorder.persist(this);if(detail==null)throw new IOException("RELEASE_WITNESS_NOT_DURABLE");}
        public Map<String,Object>details(){if(detail==null)throw new IllegalStateException("RELEASE_WITNESS_NOT_DURABLE");return detail;}
        void resolved(List<Object>refs){detail=freeze(Values.map("format","aeris-release12-cancellation","version",1,"context",owner.contextRow(),"phase",phase,"source",owner.source,"inputSequence",input.sequence,"viewEpoch",owner.epoch,"oldFence",oldFence,"newFence",newFence,"decisionNs",decisionNs,"notices",refs,"dispatchPermitEntered",false));}
    }
    private final RunLifecycle.Context context;private final String source,provenance;private final long epoch;private final RunLifecycle.Clock clock;private final AtomicReference<State>state=new AtomicReference<>(new State(0,0,Collections.emptyList()));private volatile Recorder recorder;
    public ReleaseControl(RunLifecycle.Context c,String s,String p,long e,RunLifecycle.Clock clock){context=Objects.requireNonNull(c);source=Objects.requireNonNull(s);provenance=Objects.requireNonNull(p);epoch=e;this.clock=clock;}
    public void recorder(Recorder r){if(recorder!=null)throw new IllegalStateException("RELEASE_RECORDER_ONCE");recorder=Objects.requireNonNull(r);}
    public long fence(){return state.get().fence;}
    /** Unknown context invalidation remains fatal, with no manufactured release notice. */
    public void invalidate(){for(;;){State s=state.get();if(state.compareAndSet(s,new State(Math.addExact(s.fence,1),s.permit,s.history)))return;}}
    private Map<String,Object>contextRow(){return Values.map("run",context.run,"epoch",context.epoch,"boot",context.boot,"operator",context.operator,"generation",context.generation,"profileId",context.profileId);}
    private static long integer(Object o)throws IOException{if(!(o instanceof Integer||o instanceof Long))throw new IOException("RELEASE_INTEGER");return ((Number)o).longValue();}
    public Notice publish(Map<String,Object>motion,long touchRevision,long releaseRevision,long uiThreadId,boolean fg,boolean focus,boolean fly)throws Exception{
        Map<String,Object>raw=freeze(motion);if(!raw.keySet().equals(new HashSet<>(Arrays.asList("source","kind","side","eventSource","deviceId","flags","action","eventUptimeMs","downUptimeMs","receiptElapsedNs","viewWidthPx","viewHeightPx","radiusPx","points","history"))))throw new IOException("RELEASE_MOTION_FIELDS");if(!(raw.get("radiusPx")instanceof Number)||((Number)raw.get("radiusPx")).doubleValue()<=0||!(raw.get("points")instanceof List)||!(raw.get("history")instanceof List)||((List<?>)raw.get("points")).size()<1||((List<?>)raw.get("points")).size()>2||((List<?>)raw.get("history")).size()>32)throw new IOException("RELEASE_MOTION_BOUNDS");long at=clock.monotonicNs(),receipt=integer(raw.get("receiptElapsedNs")),action=integer(raw.get("action"));
        if(epoch<=0||!Arrays.asList(0L,1L).contains(integer(raw.get("side")))||integer(raw.get("downUptimeMs"))<0||!fg||!focus||!fly||uiThreadId<=0||touchRevision<=0||releaseRevision<=0||!source.equals(raw.get("source"))||!"ANDROID_MOTION_EVENT".equals(raw.get("kind"))||!Arrays.asList(1L,3L,6L).contains(action)||receipt<0||receipt>at||at-receipt>ControlAuthority.TTL_NS||integer(raw.get("eventUptimeMs"))<0||integer(raw.get("downUptimeMs"))>integer(raw.get("eventUptimeMs"))||integer(raw.get("eventUptimeMs"))>receipt/1000000||integer(raw.get("viewWidthPx"))<=0||integer(raw.get("viewHeightPx"))<=0||(integer(raw.get("eventSource"))&4098)!=4098)throw new IOException("TRUSTED_CURRENT_RELEASE_CONTEXT_REQUIRED");
        Map<String,Object>mc=new LinkedHashMap<>();for(String k:Arrays.asList("action","side","eventSource","deviceId","flags","eventUptimeMs","downUptimeMs","receiptElapsedNs","viewWidthPx","viewHeightPx"))mc.put(k,raw.get(k));
        for(;;){State s=state.get();if(!s.history.isEmpty()){Notice previous=s.history.get(s.history.size()-1);if(touchRevision<=previous.touchRevision||releaseRevision<=((Number)previous.row().get("releaseRevision")).longValue())throw new IOException("RELEASE_REPLAY_OR_REVISION");}long next=Math.addExact(s.fence,1);Map<String,Object>r=Values.map("format","aeris-release12-notice","version",1,"context",contextRow(),"source",source,"inputProvenance",provenance,"viewEpoch",epoch,"oldFence",s.fence,"newFence",next,"releaseId",context.run+":"+next,"observedAtNs",null,"permitSerialAtRelease",s.permit,"uiThreadId",uiThreadId,"touchRevision",touchRevision,"releaseRevision",releaseRevision,"motionRawSHA256",Values.hash(Values.bytes(raw)),"motionContext",mc,"axes",Arrays.asList(0,0,0,0),"pointers",0,"foreground",true,"focused",true,"presentedFly",true);Notice n=new Notice(r,raw,s.fence,next,touchRevision,clock);List<Notice>h=new ArrayList<>(s.history);h.add(n);if(h.size()>16)h.remove(0);if(state.compareAndSet(s,new State(next,s.permit,Collections.unmodifiableList(h)))){n.materialize();return n;}}
    }
    private void context(ControlAuthority.Input i)throws Exception{if(i==null||!context.equals(i.context)||!source.equals(i.source)||!provenance.equals(i.provenance)||i.inputObservation==null||!Long.valueOf(epoch).equals(i.inputObservation.get("viewEpoch"))||!(i.inputObservation.get("releaseFence")instanceof Long))throw new IOException("SELECTED_SAMPLER_CONTEXT_RELEASE_FENCE_REQUIRED");}
    /** Structural identity is checked before ordinary temporal expiry can be classified. */
    public void admissionContext(ControlAuthority.Input input)throws Exception{
        context(input);State current=state.get();long old=(Long)input.inputObservation.get("releaseFence");
        if(old<0||old>current.fence||current.fence-old>16)throw new IOException("UNPROVEN_RELEASE_FENCE_CHANGE");
        if(old==current.fence)return;long expected=old;
        for(Notice notice:current.history)if(notice.oldFence>=old){Map<String,Object>row=notice.row();if(notice.oldFence!=expected||!row.get("uiThreadId").equals(input.inputObservation.get("uiThreadId"))||notice.touchRevision<=((Long)input.inputObservation.get("touchRevision")))throw new IOException("UNPROVEN_RELEASE_FENCE_CHANGE");expected=notice.newFence;}
        if(expected!=current.fence)throw new IOException("RELEASE_CAUSE_HISTORY_MISSING");
    }
    private Cancel cancellation(ControlAuthority.Input i,long now,String phase,State s)throws Exception {
        context(i);if(now<i.elapsedNs||now-i.elapsedNs>ControlAuthority.TTL_NS||!(i.inputObservation.get("uiHeartbeatElapsedNs")instanceof Long)||(Long)i.inputObservation.get("uiHeartbeatElapsedNs")>i.elapsedNs||now-(Long)i.inputObservation.get("uiHeartbeatElapsedNs")>ControlAuthority.TTL_NS)throw new IOException("INPUT_UI_EXPIRED_AT_RELEASE_DECISION");long old=(Long)i.inputObservation.get("releaseFence");if(old==s.fence)return null;if(old<0||old>s.fence||s.fence-old>16)throw new IOException("UNPROVEN_RELEASE_FENCE_CHANGE");List<Notice>out=new ArrayList<>();long expected=old;for(Notice n:s.history)if(n.oldFence>=old){if(n.oldFence!=expected||((Number)((Map<?,?>)n.row().get("motionContext")).get("receiptElapsedNs")).longValue()<(Long)i.inputObservation.get("uiHeartbeatElapsedNs")||n.observedAtNs()>now||now-n.observedAtNs()>ControlAuthority.TTL_NS||!n.row().get("uiThreadId").equals(i.inputObservation.get("uiThreadId"))||n.touchRevision<=((Long)i.inputObservation.get("touchRevision")))throw new IOException("RELEASE_HISTORY_CLOCK_REVISION_OR_GAP");out.add(n);expected=n.newFence;}if(expected!=s.fence||out.isEmpty())throw new IOException("RELEASE_CAUSE_HISTORY_MISSING");return new Cancel(this,i,phase,old,s.fence,now,out);
    }
    public void check(ControlAuthority.Input i,long now,String phase)throws Exception{checkedDecision(i,now,phase);}
    public long checkedDecision(ControlAuthority.Input i,long floorNs,String phase)throws Exception{for(;;){State s=state.get();for(Notice notice:s.history)notice.materialize();long observed=clock.monotonicNs();if(observed<floorNs)throw new IOException("RELEASE_DECISION_CLOCK_REGRESSION");Cancel c=epoch<=0?null:cancellation(i,observed,phase,s);if(state.get()!=s)continue;if(c!=null)throw c;return observed;}}
    public Permit enter(ControlAuthority.Input i,long now)throws Exception{return enter(i,now,()->{});}
    public Permit enter(ControlAuthority.Input i,long now,NativeSegments.Approval fresh)throws Exception{if(epoch<=0)return new Permit(0,0,now);for(;;){State s=state.get();for(Notice notice:s.history)notice.materialize();fresh.check();long observed=clock.monotonicNs();if(observed<now)throw new IOException("RELEASE_DECISION_CLOCK_REGRESSION");Cancel c=cancellation(i,observed,"DISPATCH_ENTRY",s);if(c!=null)throw c;State next=new State(s.fence,Math.addExact(s.permit,1),s.history);if(state.compareAndSet(s,next))return new Permit(next.permit,s.fence,observed);}}
    public static Map<String,Object> freeze(Map<String,Object> m){if(m==null)throw new IllegalArgumentException("NULL_RELEASE_MAP");return (Map<String,Object>)deep(m);}
    private static Object deep(Object v){if(v instanceof Map){Map<String,Object>m=new LinkedHashMap<>();for(Object k:((Map<?,?>)v).keySet()){if(!(k instanceof String))throw new IllegalArgumentException("RELEASE_MAP_KEY");m.put((String)k,deep(((Map<?,?>)v).get(k)));}return Collections.unmodifiableMap(m);}if(v instanceof List){List<Object>l=new ArrayList<>();for(Object e:(List<?>)v)l.add(deep(e));return Collections.unmodifiableList(l);}if(v instanceof Number&&!(v instanceof Integer||v instanceof Long||v instanceof Float||v instanceof Double))throw new IllegalArgumentException("RELEASE_MUTABLE_NUMBER_TYPE");if(v instanceof Number&&!Double.isFinite(((Number)v).doubleValue()))throw new IllegalArgumentException("RELEASE_NONFINITE");if(v==null||v instanceof String||v instanceof Number||v instanceof Boolean)return v;throw new IllegalArgumentException("RELEASE_VALUE_TYPE");}
}
